import{_ as i,a as t,b as a}from"./chunks/taux-fixe-ajustements.mlNDZfoW.js";import{_ as o,c as s,o as n,ae as r}from"./chunks/framework.DBgX5bsf.js";const b=JSON.parse('{"title":"Configuring Shipping Methods in Drupal Commerce","description":"","frontmatter":{},"headers":[],"relativePath":"en/docs/commerce/livraison.md","filePath":"en/docs/commerce/livraison.md"}'),p={name:"en/docs/commerce/livraison.md"};function h(d,e,l,g,m,c){return n(),s("div",null,e[0]||(e[0]=[r('<h1 id="configuring-shipping-methods-in-drupal-commerce" tabindex="-1">Configuring Shipping Methods in Drupal Commerce <a class="header-anchor" href="#configuring-shipping-methods-in-drupal-commerce" aria-label="Permalink to &quot;Configuring Shipping Methods in Drupal Commerce&quot;">​</a></h1><p>The shipping environment comes preconfigured with dummy shipping methods. These methods can be modified, deleted, or supplemented with new options according to your needs. Shipping method configuration is done in the <code>Configuration</code> -&gt; <code>Commerce</code> -&gt; <code>Shipping</code> menu.</p><p><img src="'+i+'" alt="Shipping methods management"></p><h2 id="essential-fields-for-configuring-a-shipping-method" tabindex="-1">Essential Fields for Configuring a Shipping Method <a class="header-anchor" href="#essential-fields-for-configuring-a-shipping-method" aria-label="Permalink to &quot;Essential Fields for Configuring a Shipping Method&quot;">​</a></h2><p>The key elements to fill in when configuring a shipping method are as follows:</p><ul><li><strong>Name</strong>: Identifier for the shipping method (visible only to the administrator).</li><li><strong>Plugin</strong>: Type of shipping method.</li><li><strong>Rate label</strong>: Label for the shipping method (displayed to the customer).</li><li><strong>Rate amount</strong>: Shipping fee amount.</li><li><strong>Enabled</strong>: Status of the shipping method (active or inactive).</li></ul><h2 id="types-of-shipping-methods" tabindex="-1">Types of Shipping Methods <a class="header-anchor" href="#types-of-shipping-methods" aria-label="Permalink to &quot;Types of Shipping Methods&quot;">​</a></h2><p>Two types of shipping methods are available:</p><ol><li><strong>Flat Rate</strong></li><li><strong>Flat Rate per Item</strong></li></ol><h3 id="_1-flat-rate" tabindex="-1">1. Flat Rate <a class="header-anchor" href="#_1-flat-rate" aria-label="Permalink to &quot;1. Flat Rate&quot;">​</a></h3><p>The <strong>Flat Rate</strong> shipping method applies fixed shipping fees, regardless of the number of items ordered, the weight of the order, or other factors. The shipping cost remains the same for all orders. This option can be adjusted to offer greater flexibility. For example, it is possible to define separate shipping fees for different geographical zones based on weight, product quantity, etc.</p><h3 id="_2-flat-rate-per-item" tabindex="-1">2. Flat Rate per Item <a class="header-anchor" href="#_2-flat-rate-per-item" aria-label="Permalink to &quot;2. Flat Rate per Item&quot;">​</a></h3><p>The <strong>Flat Rate per Item</strong> shipping method applies fixed shipping fees for each item ordered. The shipping cost is therefore proportional to the number of items. This option can also be customized to adapt to specific criteria, such as the delivery zone, weight, or product quantity.</p><h2 id="customizing-shipping-fees" tabindex="-1">Customizing Shipping Fees <a class="header-anchor" href="#customizing-shipping-fees" aria-label="Permalink to &quot;Customizing Shipping Fees&quot;">​</a></h2><h3 id="adjustment-based-on-user-criteria" tabindex="-1">Adjustment Based on User Criteria <a class="header-anchor" href="#adjustment-based-on-user-criteria" aria-label="Permalink to &quot;Adjustment Based on User Criteria&quot;">​</a></h3><p>Shipping fees can be adjusted based on user-related criteria. For example:</p><ul><li><strong>Billing Address</strong>: Define variable shipping fees based on the billing address.</li><li><strong>Shipping Address</strong>: Define variable shipping fees based on the shipping address.</li></ul><p><img src="'+t+'" alt="Adjustment based on user"></p><h3 id="adjustment-based-on-shipping-criteria" tabindex="-1">Adjustment Based on Shipping Criteria <a class="header-anchor" href="#adjustment-based-on-shipping-criteria" aria-label="Permalink to &quot;Adjustment Based on Shipping Criteria&quot;">​</a></h3><p>Shipping fees can also be adjusted based on order-specific criteria, such as:</p><ul><li><strong>Shipment Quantity</strong>: Define variable shipping fees based on the quantity of items ordered.</li><li><strong>Shipment Weight</strong>: Define variable shipping fees based on the total weight of the order.</li></ul><p><img src="'+a+'" alt="Shipping fee adjustments"></p>',22)]))}const _=o(p,[["render",h]]);export{b as __pageData,_ as default};
